SEC-REDIRECT-001.remediation:
Validate all redirect destinations against an allowlist:

Option 1: Allowlist-based (recommended):
const ALLOWED_REDIRECT_HOSTS = ['yourdomain.com', 'www.yourdomain.com'];

function safeRedirect(res, url) {
  try {
    const parsed = new URL(url);
    if (ALLOWED_REDIRECT_HOSTS.includes(parsed.hostname)) {
      return res.redirect(url);
    }
  } catch {}
  return res.redirect('/'); // Safe default
}

Option 2: Relative paths only:
if (url.startsWith('/') && !url.startsWith('//')) {
  res.redirect(url);
} else {
  res.redirect('/');
}

