function safe_redirect($url) {
    $allowed = ['yourdomain.com'];
    $host = parse_url($url, PHP_URL_HOST);
    if (in_array($host, $allowed) || strpos($url, '/') === 0) {
        header('Location: ' . $url);
    } else {
        header('Location: /');
    }
}

